    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        try {

            int rowCount = jTable1.getRowCount();
            for (int i = 0; i < rowCount; i++) {
                String aname = jTable1.getValueAt(i, 0).toString();

                ResultSet rs = MyDB.search("select PackCustomer.idCustomer,PackCustomer.Name,PackCustomer.NIC,PackCustomer.Phone,PackCustomer.Mobile,PackCustomer.Email FROM PackCustomer RIGHT JOIN InvoiceP on PackCustomer.idCustomer=InvoiceP.PackCustomer_idCustomer RIGHT JOIN Cheque ON InvoiceP.InvoiceP= Cheque.InvoiceP_InvoiceP where Cheque.ChequeNo='" + aname + "'");
                while (rs.next()) {

                    String n = rs.getString(1);
                    String n2 = rs.getString(2);
                    String n3 = rs.getString(3);
                    String n4 = rs.getString(4);
                    String n5 = rs.getString(5);
                    String n6 = rs.getString(6);
                    customer_de.getOb().setVisible(true);
                    // new customer_de().setVisible(true);
                    customer_de.interTointer(n, n2, n3, n4, n5, n6);

                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }//GEN-LAST:event_jButton2ActionPerformed

