    private void jButton3ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton3ActionPerformed
        try {

            int rowCount = jTable1.getRowCount();
            for (int i = 0; i < rowCount; i++) {
                String a = jTable1.getValueAt(i, 0).toString();

                ResultSet rs = MyDB.search("select i.InvoiceP,i.date,i.subtotal,i.discount,i.netTotal,i.payment,i.Balance,DueAmount from invoicep i join Cheque c on i.InvoiceP=c.InvoiceP_InvoiceP where c.chequeNo='"+a+"' ");
                while (rs.next()) {

                    String n = rs.getString(1);
                    String n2 = rs.getString(2);
                    String n3 = rs.getString(3);
                    String n4 = rs.getString(4);
                    String n5 = rs.getString(5);
                    String n6 = rs.getString(6);
                    String n7 = rs.getString(7);
                    String n8 = rs.getString(8);
                    
                   Cheqe_invoice_report.getob().setVisible(true);
                    // new customer_de().setVisible(true);
                   Cheqe_invoice_report.interTointer(n, n2, n3, n4, n5, n6,n7,n8);

                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }//GEN-LAST:event_jButton3ActionPerformed

