    private void returntableload() {
        try {
            ResultSet r = MyDB.search("select ChequeNo,ChequeDate,ChequeValue,ChequeType from Cheque where status='Return'");
            DefaultTableModel tb = (DefaultTableModel) jTable1.getModel();
            while (r.next()) {
                Vector v = new Vector();
                v.add(r.getString(1));
                v.add(r.getString(2));
                v.add(r.getString(3));
                v.add(r.getString(4));

                tb.addRow(v);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }



